func pacificAtlantic(heights [][]int) [][]int {
	m, n := len(heights), len(heights[0])
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	flow := func(starts [][2]int) [][]bool {
		seen := make([][]bool, m)
		for i := range seen {
			seen[i] = make([]bool, n)
		}
		stack := [][2]int{}
		for _, s := range starts {
			if !seen[s[0]][s[1]] {
				seen[s[0]][s[1]] = true
				stack = append(stack, s)
			}
		}
		for len(stack) > 0 {
			p := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			for _, d := range dirs {
				nx, ny := p[0]+d[0], p[1]+d[1]
				if nx >= 0 && nx < m && ny >= 0 && ny < n && !seen[nx][ny] &&
					heights[nx][ny] >= heights[p[0]][p[1]] {
					seen[nx][ny] = true
					stack = append(stack, [2]int{nx, ny})
				}
			}
		}
		return seen
	}
	starts := [][2]int{}
	for j := 0; j < n; j++ {
		starts = append(starts, [2]int{0, j})
	}
	for i := 0; i < m; i++ {
		starts = append(starts, [2]int{i, 0})
	}
	pac := flow(starts)
	starts = [][2]int{}
	for j := 0; j < n; j++ {
		starts = append(starts, [2]int{m - 1, j})
	}
	for i := 0; i < m; i++ {
		starts = append(starts, [2]int{i, n - 1})
	}
	atl := flow(starts)
	res := [][]int{}
	for i := 0; i < m; i++ {
		for j := 0; j < n; j++ {
			if pac[i][j] && atl[i][j] {
				res = append(res, []int{i, j})
			}
		}
	}
	return res
}

