func acyclic(edges [][]int, skip int, n int) bool {
	parent := make([]int, n+1)
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	for i, e := range edges {
		if i == skip {
			continue
		}
		ru, rv := find(e[0]), find(e[1])
		if ru == rv {
			return false
		}
		parent[ru] = rv
	}
	return true
}

