func largestIsland(grid [][]int) int {
	n := len(grid)
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	label := make([][]int, n)
	for i := range label {
		label[i] = make([]int, n)
	}
	area := []int{0}
	cur := 0
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if grid[i][j] != 1 || label[i][j] != 0 {
				continue
			}
			cur++
			label[i][j] = cur
			stack := [][2]int{{i, j}}
			size := 0
			for len(stack) > 0 {
				p := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				size++
				for _, d := range dirs {
					nx, ny := p[0]+d[0], p[1]+d[1]
					if nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 1 &&
						label[nx][ny] == 0 {
						label[nx][ny] = cur
						stack = append(stack, [2]int{nx, ny})
					}
				}
			}
			area = append(area, size)
		}
	}
	best := 0
	for _, a := range area {
		if a > best {
			best = a
		}
	}
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			if grid[i][j] != 0 {
				continue
			}
