func findTheCity(n int, edges [][]int, distanceThreshold int) int {
	const INF = 1 << 30
	dist := make([][]int, n)
	for i := range dist {
		dist[i] = make([]int, n)
		for j := 0; j < n; j++ {
			dist[i][j] = INF
		}
		dist[i][i] = 0
	}
	for _, e := range edges {
		dist[e[0]][e[1]] = e[2]
		dist[e[1]][e[0]] = e[2]
	}
	for p := 0; p < n; p++ {
		for i := 0; i < n; i++ {
			if dist[i][p] == INF {
				continue
			}
			for j := 0; j < n; j++ {
				if nd := dist[i][p] + dist[p][j]; nd < dist[i][j] {
					dist[i][j] = nd
				}
			}
		}
	}
	best := n + 1
	ans := 0
	for i := 0; i < n; i++ {
		cnt := 0
		for j := 0; j < n; j++ {
			if i != j && dist[i][j] <= distanceThreshold {
				cnt++
			}
		}
		if cnt <= best {
			best = cnt
			ans = i
		}
	}
	return ans
}

